import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (position/rotation/scale applied by adapter)
  const root = new Group();

  // -------------------------------------------------
  // 1. Textured plane (render mode: plane)
  // -------------------------------------------------
  const planeGeom = new PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously, assign when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // -------------------------------------------------
  // 2. Text content via fontAtlas
  // -------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const txt = item.text ?? '';
    const fontSize = item.typography?.fontSize ?? 39; // default from spec
    const color = (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2';
    const textObj = ctx.fontAtlas.createText(txt, {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly in front of the plane to avoid Z‑fighting
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
    textObjects.push(textObj);
  }

  // -------------------------------------------------
  // 3. Cinematic primitives (none in this spec)
  // -------------------------------------------------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const handle = fn(root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // -------------------------------------------------
  // 4. Event handlers placeholder
  // -------------------------------------------------
  root.userData.handlers = {};

  // -------------------------------------------------
  // 5. Cleanup routine
  // -------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose loaded texture if any
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    // Dispose any text objects (their internal resources)
    for (const txt of textObjects) {
      if (txt.geometry) txt.geometry.dispose();
      if (txt.material) txt.material.dispose();
    }

    // Cleanup primitives
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }

    // Kill any GSAP timelines (none used here but defensive)
    gsap.globalTimeline.clear();
  };

  return root;
}
